"""inspect_image: read-only vision tool with fail-closed routing."""
from __future__ import annotations
import base64
import io
import json
import urllib.error
import pytest
from minicode.tools.inspect_image import inspect_image_tool
from minicode.tooling import ToolContext
_PNG_BYTES = base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4/z8AAwMBAAJDAXQAAAAASUVORK5CYII=')
_RUNTIME = {'model': 'fake-parent', 'visionModel': 'qwen-vl-max', 'subagentBaseUrl': 'https://dashscope.example.com/compatible-mode/v1', 'subagentApiKey': 'sk-test'}

class _Response:

    def __init__(self, payload: dict, status: int=200) -> None:
        self._payload = payload
        self.status = status

    def read(self) -> bytes:
        return json.dumps(self._payload).encode('utf-8')

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False

def _ok_payload(text: str='A white 1x1 pixel.') -> dict:
    return {'choices': [{'message': {'content': text}}], 'usage': {'total_tokens': 42}}

def _capture(captured, payload=None, error=None):

    def fake(request, timeout=60):
        captured.append({'url': request.full_url, 'headers': dict(request.headers), 'body': json.loads(request.data.decode('utf-8'))})
        if error is not None:
            raise error
        return _Response(payload or _ok_payload())
    return fake

def _context(tmp_path, runtime=None) -> ToolContext:
    return ToolContext(cwd=str(tmp_path), _runtime=runtime or _RUNTIME)

def _write_png(tmp_path, name='pixel.png', data=_PNG_BYTES):
    target = tmp_path / name
    target.write_bytes(data)
    return target

def test_rejects_non_image_extension(tmp_path, monkeypatch):
    target = tmp_path / 'notes.txt'
    target.write_bytes(_PNG_BYTES)
    result = inspect_image_tool.run({'path': 'notes.txt', 'question': 'what is this?'}, _context(tmp_path))
    assert not result.ok
    assert 'extension' in result.output

def test_rejects_disguised_image(tmp_path):
    target = _write_png(tmp_path, 'fake.png', b'this is plain text, not an image')
    result = inspect_image_tool.run({'path': 'fake.png', 'question': 'what?'}, _context(tmp_path))
    assert not result.ok
    assert 'magic' in result.output or 'image' in result.output

def test_rejects_network_url(tmp_path):
    result = inspect_image_tool.run({'path': 'https://evil.example.com/x.png', 'question': 'what?'}, _context(tmp_path))
    assert not result.ok
    assert 'network_url_rejected' in result.output or 'local' in result.output

def test_rejects_oversized_file(tmp_path, monkeypatch):
    import minicode.tools.inspect_image as module
    target = _write_png(tmp_path, 'big.png')
    monkeypatch.setattr(module, '_MAX_IMAGE_BYTES', 10)
    result = inspect_image_tool.run({'path': 'big.png', 'question': 'what?'}, _context(tmp_path))
    assert not result.ok
    assert 'too_large' in result.output

def test_missing_vision_model_fails_closed(tmp_path):
    runtime = dict(_RUNTIME)
    runtime.pop('visionModel')
    _write_png(tmp_path)
    result = inspect_image_tool.run({'path': 'pixel.png', 'question': 'what?'}, _context(tmp_path, runtime))
    assert not result.ok
    assert 'vision_model_unconfigured' in result.output

def test_visual_key_in_subagent_models_suffices(tmp_path, monkeypatch):
    captured: list[dict] = []
    monkeypatch.setattr('urllib.request.urlopen', _capture(captured, payload=_ok_payload('ok')))
    runtime = {'subagentModels': {'visual': 'qwen-vl-plus'}, 'subagentBaseUrl': 'https://dashscope.example.com/v1', 'subagentApiKey': 'sk-test'}
    _write_png(tmp_path)
    result = inspect_image_tool.run({'path': 'pixel.png', 'question': 'describe'}, _context(tmp_path, runtime))
    assert result.ok, result.output
    assert captured[0]['body']['model'] == 'qwen-vl-plus'

def test_missing_credentials_fail_closed(tmp_path):
    _write_png(tmp_path)
    for runtime in ({'visionModel': 'm'}, {'visionModel': 'm', 'subagentBaseUrl': 'https://x.example.com'}, {'visionModel': 'm', 'subagentBaseUrl': 'http://insecure.example.com', 'subagentApiKey': 'k'}):
        result = inspect_image_tool.run({'path': 'pixel.png', 'question': 'what?'}, _context(tmp_path, runtime))
        assert not result.ok, runtime
